<template>
  <router-link to="/landing">
    <svg
      id="back"
      width="50"
      height="50"
      viewBox="0 0 50 50"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlns:xlink="http://www.w3.org/1999/xlink"
    >
      <rect width="50" height="50" fill="url(#pattern0_874_2632)" />
      <defs>
        <pattern
          id="pattern0_874_2632"
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use xlink:href="#image0_874_2632" transform="scale(0.002)" />
        </pattern>
        <image
          id="image0_874_2632"
          width="500"
          height="500"
          preserveAspectRatio="none"
          xlink:href="data:image/png;base64,"
        />
      </defs>
    </svg>
  </router-link>

  <main>
    <h1>Select the desired location</h1>

    <div class="search-wrapper">
      <div class="search-bar">
        <input
          type="text"
          v-model="query"
          @input="onInput"
          @focus="onFocus"
          @blur="onBlur"
          @keyup.enter="search"
        />
        <svg
          width="68"
          height="101"
          viewBox="0 0 68 101"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          xmlns:xlink="http://www.w3.org/1999/xlink"
        >
          <path
            d="M0 12C0 5.37258 5.37258 0 12 0H55.5C62.1274 0 67.5 5.37258 67.5 12V88.57C67.5 95.1974 62.1274 100.57 55.5 100.57H12C5.37258 100.57 0 95.1974 0 88.57V12Z"
            fill="url(#pattern0_874_2612)"
          />
          <defs>
            <pattern
              id="pattern0_874_2612"
              patternContentUnits="objectBoundingBox"
              width="1"
              height="1"
            >
              <use
                xlink:href="#image0_874_2612"
                transform="matrix(0.00195312 0 0 0.00131089 0 0.164413)"
              />
            </pattern>
            <image
              id="image0_874_2612"
              width="512"
              height="512"
              preserveAspectRatio="none"
              xlink:href="data:image/png;base64,"
            />
          </defs>
        </svg>
      </div>

      <!-- dropdown -->
      <ul v-if="showDropdown && filteredCities.length" class="search-dropdown">
        <li
          v-for="city in filteredCities"
          :key="city"
          @mousedown.prevent="selectCity(city)"
        >
          {{ city }},
          {{ apiCityCountryMap[city] || cityCountryMap[city] || "Unknown" }}
        </li>
      </ul>
    </div>

    <h1>Popular choices</h1>

    <div class="container">
      <div
        class="option"
        v-for="name in cities"
        :key="name"
        @click="selectCity(name)"
      >
        <img :src="`/images/${name.toLowerCase()}.png`" :alt="name" />
        <h4>{{ name }}</h4>
      </div>
    </div>
  </main>
</template>

<script>
import { computed, ref, onMounted } from "vue";
import { useRouter } from "vue-router";
import { useStore } from "@/stores/store";

export default {
  name: "PopularCities",

  data() {
    const router = useRouter();
    const store = useStore();

    // datas base do slider etc. não são precisas aqui, só cidades
    return {
      router,
      store,

      // cidades populares já existentes (mantém as 6)
      cities: ["London", "Porto", "Chicago", "Brussels", "Vienna", "Paris"],

      cityCountryMap: {
        London: "ENGLAND",
        Porto: "PORTUGAL",
        Chicago: "USA",
        Brussels: "BELGIUM",
        Vienna: "AUSTRIA",
        Paris: "FRANCE",
      },

      // mapeamento dinâmico vindo da API
      apiCityCountryMap: {},

      // estado da search bar e dropdown
      query: "",
      showDropdown: false,
    };
  },

  computed: {
    // conjunto de todas as cidades “pesquisáveis”
    allSearchableCities() {
      const fromApi = Object.keys(this.apiCityCountryMap);
      const fromStatic = Object.keys(this.cityCountryMap);
      const set = new Set([...fromApi, ...fromStatic]);
      return Array.from(set);
    },

    // opções mostradas no dropdown (máx. 4)
    filteredCities() {
      const q = this.query.trim().toLowerCase();
      if (!q) return [];
      return this.allSearchableCities
        .filter((city) => city.toLowerCase().includes(q))
        .slice(0, 4);
    },
  },

  methods: {
    // selecionar cidade (popular ou do dropdown)
    selectCity(city) {
      const country =
        this.apiCityCountryMap[city] || this.cityCountryMap[city] || "UNKNOWN";
      this.store.setCity(city, country);
      this.router.push("/dashboard");
    },

    // carregar endpoints da API e preencher apiCityCountryMap
    async fetchCitiesFromApi() {
      try {
        const res = await fetch("http://localhost:3000/");
        const html = await res.text();

        const regex = /href="([^"]+\.neighbourhoods)"/g;
        const map = {};
        let match;

        while ((match = regex.exec(html)) !== null) {
          const path = match[1].replace("http://localhost:3000/", "");
          const [countryRaw, cityRaw] = path.split(".");
          if (!countryRaw || !cityRaw) continue;

          const country = countryRaw.toUpperCase();
          const city =
            cityRaw.charAt(0).toUpperCase() + cityRaw.slice(1).toLowerCase();

          map[city] = country;
        }

        this.apiCityCountryMap = map;
      } catch (e) {
        console.error("Erro ao carregar cidades da API", e);
        this.apiCityCountryMap = {};
      }
    },

    onInput() {
      this.showDropdown = this.filteredCities.length > 0;
    },

    onFocus() {
      this.showDropdown = this.filteredCities.length > 0;
    },

    onBlur() {
      setTimeout(() => {
        this.showDropdown = false;
      }, 150);
    },

    // ao carregar Enter usa a primeira sugestão (se existir)
    search() {
      if (!this.query.trim()) return;
      if (this.filteredCities.length > 0) {
        this.selectCity(this.filteredCities[0]);
      }
    },
  },

  created() {
    this.fetchCitiesFromApi();
  },
};
</script>

